using System.Security.Cryptography;
using System.Text;

namespace EvalToolkit.Core;

/// <summary>
/// Stable, deterministic identifier generation for eval items, facts,
/// and rows. The TS implementation uses xxhash-of-content for item ids
/// so the same input produces the same id across runs and across
/// implementations; the C# port must produce identical strings or the
/// <c>EvalSet.items[].id</c> field would silently diverge.
///
/// **xxhash parity matters** because eval files generated by either
/// app must be interchangeable. We pull <c>System.IO.Hashing</c> for
/// the matching algorithm rather than reaching for SHA-256 (which
/// would produce different ids).
/// </summary>
public static class StableIds
{
    /// <summary>
    /// Compute a deterministic, URL-safe id from one or more content
    /// strings. The strings are joined with a NUL separator (so two
    /// inputs that would concatenate to the same string still get
    /// distinct ids) and hashed.
    ///
    /// The current implementation uses SHA-256 truncated to 16 bytes
    /// rendered as base32-without-padding. **Will be swapped to xxhash3
    /// in the <c>readers-port</c> todo once the
    /// <c>System.IO.Hashing</c> package is wired up via CPM</c>** so the
    /// output matches the TS impl byte-for-byte. Until then, this is a
    /// placeholder so types compile.
    /// </summary>
    /// <remarks>
    /// xxhash3 is significantly faster than SHA-256 and the TS impl
    /// relies on xxhash3 specifically. SHA-256-then-truncate is used
    /// here only because <c>System.IO.Hashing</c> isn't a transitive
    /// dep yet; the truncated hash is still collision-safe for the
    /// scale of eval sets we generate (low millions max), so this
    /// placeholder is safe for non-parity-gated unit tests.
    /// </remarks>
    public static string ContentId(params string[] parts)
    {
        ArgumentNullException.ThrowIfNull(parts);
        if (parts.Length == 0)
        {
            throw new ArgumentException("ContentId requires at least one input.", nameof(parts));
        }
        StringBuilder joined = new();
        for (int i = 0; i < parts.Length; i++)
        {
            if (i > 0)
            {
                joined.Append('\0');
            }
            joined.Append(parts[i] ?? string.Empty);
        }
        byte[] hash = SHA256.HashData(Encoding.UTF8.GetBytes(joined.ToString()));
        return Base32NoPad(hash.AsSpan(0, 16));
    }

    private static string Base32NoPad(ReadOnlySpan<byte> bytes)
    {
        // RFC 4648 base32 alphabet, no padding. Produces URL-safe ids.
        const string Alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";
        StringBuilder sb = new(bytes.Length * 8 / 5 + 1);
        int buffer = 0;
        int bitsLeft = 0;
        foreach (byte b in bytes)
        {
            buffer = (buffer << 8) | b;
            bitsLeft += 8;
            while (bitsLeft >= 5)
            {
                int index = (buffer >> (bitsLeft - 5)) & 0x1F;
                sb.Append(Alphabet[index]);
                bitsLeft -= 5;
            }
        }
        if (bitsLeft > 0)
        {
            int index = (buffer << (5 - bitsLeft)) & 0x1F;
            sb.Append(Alphabet[index]);
        }
        return sb.ToString();
    }
}
